#include <stdio.h>
#include <string.h>

int main(void) {
    const char *order[] = {"1", "logn", "n", "nlogn", "n2", "n3", "2n"};
    bool present[7] = {false};
    int k;
    if (scanf("%d", &k) != 1) {
        return 0;
    }
    for (int i = 0; i < k; i++) {
        char name[8];
        if (scanf("%7s", name) != 1) {
            break;
        }
        for (int r = 0; r < 7; r++) {
            if (strcmp(name, order[r]) == 0) {
                present[r] = true;
            }
        }
    }
    bool first = true;
    for (int r = 0; r < 7; r++) {
        if (present[r]) {
            printf(first ? "%s" : " %s", order[r]);
            first = false;
        }
    }
    printf("\n");
    return 0;
}

