#include <stdio.h>

static long long bit_length(long long n) {
    long long digits = 0;
    for (; n > 0; n /= 2) {
        digits++;
    }
    return digits;
}

int main(void) {
    long long a, b;
    while (scanf("%lld %lld", &a, &b) == 2) {
        long long n = 1;
        while (a * n <= b * bit_length(n)) {
            n++;
        }
        printf("%lld\n", n);
    }
    return 0;
}

