int main(void) {
    int n;
    while (scanf("%d", &n) == 1) {
        if (n < 1) {
            continue;
        }
        int steps = 0;
        int last = 0;
        for (int i = 1; i <= n; i *= 2) {
            steps++;
            last = i;
        }
        printf("%d %lld\n", steps, (long long)last);
    }
    return 0;
}

