#include <stdio.h>

int main(void) {
    long long n;
    if (scanf("%lld", &n) != 1 || n < 1) {
        return 0;
    }
    long long total = 0;
    for (long long d = 1; d <= n; d++) {
        total += d * (n / d);
    }
    printf("%lld\n", total);
    return 0;
}

